// Time zones for Temporal (ws/temporal2): identifiers, UTC offsets, possible instants, transitions.
// Spec: proposal-temporal timezone.html (§11) and mainadditions.html (GetNamedTimeZone*). The IANA data is
// generated by tools/temporal/gen-tz.mjs from node 22's ICU time zone data into tz_data.inc; there is no tz
// library at runtime. The host's local time zone (SystemTimeZoneIdentifier) is "UTC".
//
// temporal.h includes this header; it depends only on records.h (EpochNanoseconds and the ISO records). A time
// zone is a TimeZone value: no GC pointer, nothing to trace. Wall-clock times are ISO Date-Time Records.
#pragma once

#include <cstdint>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

#include "builtins/temporal/records.h"
#include "runtime/result.h"

namespace snowman {
class BigInt;
}

namespace snowman::temporal {

constexpr int64_t nsPerSecond = 1'000'000'000;
constexpr int64_t nsPerMinute = 60 * nsPerSecond;
constexpr int64_t nsPerHour = 60 * nsPerMinute;
constexpr int64_t nsPerDay = 24 * nsPerHour;
// |epoch ns| <= nsMaxInstant = 8.64 × 10^21 (74 bits).
constexpr EpochNanoseconds nsMaxInstant = EpochNanoseconds(nsPerDay) * 100'000'000;
constexpr EpochNanoseconds nsMinInstant = -nsMaxInstant;

// IsValidEpochNanoseconds (8.5.1)
constexpr bool IsValidEpochNanoseconds(EpochNanoseconds ns) { return ns >= nsMinInstant && ns <= nsMaxInstant; }

// BigInt <-> epoch nanoseconds. BigIntToEpochNanoseconds is nullopt when |x| >= 2^127 (always invalid).
std::optional<EpochNanoseconds> BigIntToEpochNanoseconds(const BigInt* x);
BigInt* EpochNanosecondsToBigInt(EpochNanoseconds ns);

// An available time zone identifier, as a [[TimeZone]] internal slot holds it: an available named time zone
// (id indexes the identifier table: the case-normalized [[Identifier]], which may be a Link name) or an offset
// time zone (id == kOffsetZone, offsetMinutes in -1439..1439).
struct TimeZone {
  static constexpr int32_t kOffsetZone = -1;
  int32_t id = kOffsetZone;
  int32_t offsetMinutes = 0;

  static TimeZone UTC();
  static TimeZone Offset(int32_t offsetMinutes) { return TimeZone{kOffsetZone, offsetMinutes}; }
  // IsOffsetTimeZoneIdentifier
  bool isOffset() const { return id == kOffsetZone; }
  bool isUTC() const;  // the named zone "UTC" or one of its links ("Etc/UTC", "GMT", ...), not "+00:00"
};

// Time Zone Identifier Parse Record: exactly one of name / offsetMinutes is set.
struct TimeZoneIdentifierParseRecord {
  std::u16string name;  // the TimeZoneIANAName source text (not yet checked for availability)
  std::optional<int32_t> offsetMinutes;
};

// ParseTimeZoneIdentifier: nullopt where the spec throws a RangeError. Offset identifiers are
// ±HH, ±HHMM or ±HH:MM (no sub-minute precision).
std::optional<TimeZoneIdentifierParseRecord> ParseTimeZoneIdentifier(std::u16string_view identifier);

// GetAvailableNamedTimeZoneIdentifier: ASCII-case-insensitive lookup; nullopt = ~empty~.
std::optional<TimeZone> GetAvailableNamedTimeZoneIdentifier(std::u16string_view name);

// The TimeZone of a parse record: an offset zone, or the available named zone (RangeError if unavailable).
// This is the tail of ToTemporalTimeZoneIdentifier and of the ZonedDateTime constructor.
Result<TimeZone> TimeZoneFromParseRecord(const TimeZoneIdentifierParseRecord& record);

// ToTemporalTimeZoneIdentifier: a ZonedDateTime's [[TimeZone]], or a String through
// ParseTemporalTimeZoneString (TypeError for non-strings, RangeError for unknown zones).
Result<TimeZone> ToTemporalTimeZoneIdentifier(Value temporalTimeZoneLike);

// The identifier String the slot holds: the case-normalized named identifier, or ±HH:MM.
std::u16string TimeZoneIdentifier(TimeZone timeZone);
// The [[PrimaryIdentifier]] of a named zone (Link names resolve to their Zone), or ±HH:MM.
std::u16string PrimaryTimeZoneIdentifier(TimeZone timeZone);
// TimeZoneEquals: same offset, or named zones with the same primary identifier.
bool TimeZoneEquals(TimeZone one, TimeZone two);

// FormatOffsetTimeZoneIdentifier: ±HH:MM (separated) or ±HHMM.
std::u16string FormatOffsetTimeZoneIdentifier(int32_t offsetMinutes, bool separated = true);
// FormatUTCOffsetNanoseconds: ±HH:MM, ±HH:MM:SS or ±HH:MM:SS.fffffffff (no trailing zeros).
std::u16string FormatUTCOffsetNanoseconds(int64_t offsetNanoseconds);
// FormatDateTimeUTCOffsetRounded: rounded half-expand to the minute, ±HH:MM.
std::u16string FormatDateTimeUTCOffsetRounded(int64_t offsetNanoseconds);

// GetOffsetNanosecondsFor: the UTC offset in effect at epochNs (an exact time, assumed valid).
int64_t GetOffsetNanosecondsFor(TimeZone timeZone, EpochNanoseconds epochNs);
// GetNamedTimeZoneOffsetNanoseconds (named zones only).
int64_t GetNamedTimeZoneOffsetNanoseconds(TimeZone timeZone, EpochNanoseconds epochNs);
// GetNamedTimeZoneNextTransition / GetNamedTimeZonePreviousTransition: the first nanosecond of the next
// (strictly after) / previous (strictly before) UTC offset change, nullopt (null) if none within the valid
// instant range. Named zones only.
std::optional<EpochNanoseconds> GetNamedTimeZoneNextTransition(TimeZone timeZone, EpochNanoseconds epochNs);
std::optional<EpochNanoseconds> GetNamedTimeZonePreviousTransition(TimeZone timeZone, EpochNanoseconds epochNs);

// GetISODateTimeFor: the wall-clock time at epochNs (valid) in timeZone. Fields are balanced.
ISODateTime GetISODateTimeFor(TimeZone timeZone, EpochNanoseconds epochNs);

// GetNamedTimeZoneEpochNanoseconds: the exact times (0, 1 or 2, ascending) whose wall-clock time in the named
// zone is isoDateTime. isoDateTime must be a valid ISO date-time; results may be out of the valid
// instant range.
std::vector<EpochNanoseconds> GetNamedTimeZoneEpochNanoseconds(TimeZone timeZone, const ISODateTime& isoDateTime);
// GetPossibleEpochNanoseconds: as above for any zone; RangeError if a result is not a valid epoch ns, or (offset
// zones) CheckISODaysRange fails.
Result<std::vector<EpochNanoseconds>> GetPossibleEpochNanoseconds(TimeZone timeZone, const ISODateTime& isoDateTime);

enum class Disambiguation { Compatible, Earlier, Later, Reject };
// DisambiguatePossibleEpochNanoseconds, GetEpochNanosecondsFor: RangeError for ~reject~ on a gap or
// an overlap, and when the chosen instant is out of range.
Result<EpochNanoseconds> DisambiguatePossibleEpochNanoseconds(const std::vector<EpochNanoseconds>& possibleEpochNs,
                                                             TimeZone timeZone, const ISODateTime& isoDateTime,
                                                             Disambiguation disambiguation);
Result<EpochNanoseconds> GetEpochNanosecondsFor(TimeZone timeZone, const ISODateTime& isoDateTime,
                                               Disambiguation disambiguation);
// GetStartOfDay: the first valid wall-clock instant of the ISO date in timeZone (RangeError if out of range).
Result<EpochNanoseconds> GetStartOfDay(TimeZone timeZone, ISODate isoDate);

// SystemTimeZoneIdentifier: always "UTC" in this engine.
TimeZone SystemTimeZoneIdentifier();
// SystemUTCEpochNanoseconds (Temporal.Now): the host clock, clamped to the valid range.
EpochNanoseconds SystemUTCEpochNanoseconds();

// The available named time zones: every case-normalized identifier (Zones and Links), and the primary ones
// (what Intl.supportedValuesOf("timeZone") lists), each sorted.
std::vector<std::u16string> AvailableNamedTimeZoneIdentifiers();
std::vector<std::u16string> AvailablePrimaryTimeZoneIdentifiers();

}  // namespace snowman::temporal
